                joined = joined + " -> ";
            }
            joined = joined + path[i];
            i = i + 1;
        }
        print("Course path: " + joined);
        return True;
    }

    nexts = prereqs_of[code];
    i = 0;
    while i < len(nexts) {
        if find_path(prereqs_of, nexts[i], target_code, path, visited) {
            return True;
        }
        i = i + 1;
    }
    path.pop();
    return False;
}

