glob records: dict[str, dict] = {};
glob adjacency: dict[str, list[str]] = {"root": []};
glob next_id: int = 1;


def create_todo(text: str) -> dict {
    global next_id;
    tid = "todo_" + str(next_id);
    next_id = next_id + 1;
    todo = {"id": tid, "text": text, "done": False};
    records[tid] = todo;
    adjacency["root"].append(tid);
    return {"status": 200, "ok": True, "reports": [todo]};
}


def read_todos -> dict {
    found: list = [];
    visited: list[str] = [];
    queue: list[str] = ["root"];
    while len(queue) > 0 {
        cur = queue.pop(0);
        if cur in visited {
            continue;
        }
        visited.append(cur);
        if cur in records {
            found.append(records[cur]);
        }
        for child in adjacency.get(cur, []) {
            queue.append(child);
        }
    }
    return {"status": 200, "ok": True, "reports": found};
}


def toggle_todo(todo_id: str) -> dict {
