def regenerate_shopping_list(meal_description: str) -> list[list[dict]] {
    global next_id;
    reports: list[list[dict]] = [];
    # Snapshot the old item ids first (they are cleared after generation)
    old_ids = [
        iid for iid in adjacency.get("root", [])
        if items_store[iid]["kind"] == "shopping_item"
    ];
    # Generate new ingredients (runs before the queued clear pass)
    ingredients = generate_shopping_list(meal_description);
    for ing in ingredients {
        iid = "item_" + str(next_id);
        next_id = next_id + 1;
        items_store[iid] = {
            "id": iid,
            "kind": "shopping_item",
            "name": ing["name"],
            "quantity": ing["quantity"],
            "unit": ing["unit"],
            "cost": ing["cost"],
            "carby": ing["carby"]
        };
        adjacency["root"].append(iid);
    }
    reports.append(
        [
            items_store[iid]
            for iid in adjacency["root"]
            if items_store[iid]["kind"] == "shopping_item"
        ]
    );
    # Clear the old items that were queued for removal
    for iid in old_ids {
        adjacency["root"].remove(iid);
        del items_store[iid];
    }
    return reports;
}

