def analyze(code: str) -> CodeAnalysis {
    # Hand-rolled analysis:
    # - issues: List of problems found
    # - suggestions: Improvement recommendations
    # - complexity_score: 1-10 complexity rating
    # - summary: One paragraph overview
    issues: list[str] = [];
