        suggestions.append("Avoid eval; parse input explicitly");
    }
    branch_count = code.count("if ") + code.count("while ") + code.count("for ");
    score = min(10, 1 + branch_count);
    return CodeAnalysis(
        issues=issues,
        suggestions=suggestions,
        complexity_score=score,
        summary=f"{len(lines)} lines, {branch_count} branch points, "
            f"{len(issues)} issues found."
    );
}

