def run_visitor(records: dict[str, dict], adjacency: dict[str, list[str]]) -> None {
    visited: list[str] = [];
    queue: list[str] = list(adjacency.get("root", []));
    while len(queue) > 0 {
        cur = queue.pop(0);
        if cur in visited {
            continue;
        }
        visited.append(cur);
        greet(records[cur]);
        meet(records[cur]);
        for child in adjacency.get(cur, []) {
            queue.append(child);
        }
    }
}

