def can_take(course_code: str, completed: list) -> bool {
    ok = True;
    # Check prerequisite links pointing into this course
    prereqs = [courses[c] for c in prereq_in.get(course_code, [])];

    for prereq in prereqs {
        if prereq["code"] not in completed {
            print(f"Missing prerequisite: {prereq['code']} - {prereq['name']}");
            ok = False;
        }
    }
    return ok;
}

def find_path(start_code: str, target_code: str) -> None {
    path: list = [];
    visited: set = set();

    def explore(code: str) -> bool {
        if code in visited {
            return False;
        }
        visited.add(code);
        path.append(code);

        if code == target_code {
            print(f"Course path: {' -> '.join(path)}");
            return True;
        }

        for nxt in prereq_out.get(code, []) {
            if explore(nxt) {
                return True;
            }
        }
        path.pop();
        return False;
    }

    explore(start_code);
}

