    for tid in root_tasks {
        task = tasks[tid];
        if task["status"] != "pending" {
            continue;
        }

        # Check if all dependencies are complete
        all_done = True;
        for dep in depends_on.get(tid, []) {
            if tasks[dep]["status"] != "complete" {
                all_done = False;
                break;
            }
        }

        if all_done {
            ready_tasks.append(task["title"]);
        }
    }
    return ready_tasks;
}

