def traverse(start_id: str) -> None {
    visited: list[str] = [];
    queue: list[str] = [start_id];
    while len(queue) > 0 {
        cur = queue.pop(0);
        if cur in visited {
            continue;
        }
        visited.append(cur);
        if nodes[cur]["kind"] == "root" {
            for e in out_edges(cur) {
                queue.append(e["target"]);
            }
        } else {
            by_person = targets_by_node_kind(cur, "person");
            by_friend = targets_by_edge_kind(cur, "friend");
            recent = friends_since_after(cur, 2020);
            print(f"{cur}: persons={by_person} friends={by_friend} recent={recent}");
            for t in recent {
                queue.append(t);
            }
        }
    }
}

