def describe(rec: dict) -> None {
    kind = rec["kind"];
    print(f"Processing {kind}...");
    if kind == "book" {
        title = rec["title"];
        author = rec["author"];
        print(f"  -> Book: '{title}' by {author}");
    } elif kind == "magazine" {
        title = rec["title"];
        issue = rec["issue"];
        print(f"  -> Magazine: '{title}' Issue #{issue}");
    } elif kind == "electronics" {
        name = rec["name"];
        warranty = rec["warranty_years"];
        print(f"  -> Electronics: {name}, warranty {warranty}yr");
    }
}

def process_cart(start_id: str) -> float {
    total = 0.0;
    visited: list[str] = [];
    stack: list[str] = [start_id];
    while len(stack) > 0 {
        cur = stack.pop();
        if cur in visited {
            continue;
        }
        visited.append(cur);
        rec = products[cur];
        describe(rec);
        total += rec["price"];
        for nxt in adj.get(cur, []) {
            stack.append(nxt);
        }
    }
    return total;
}

