def greet(item_id: str, target: str) -> None {
    # stands in for the node-side reaction to an arriving visitor
    print(f"{items[item_id]['name']} greeted by {target}");
}

def find(target: str) -> list[dict] {
    matches: list[dict] = [];
    queue: list[str] = list(children.get("root", []));
    seen: list[str] = [];
    while len(queue) > 0 {
        cur = queue.pop(0);
        if cur in seen {
            continue;
        }
        seen.append(cur);
        greet(cur, target);
        if items[cur]["name"] == target {
            matches.append(items[cur]);
        }
        for nxt in children.get(cur, []) {
            queue.append(nxt);
        }
    }
    return matches;
}

