"""Convert a stored ESTree node record to a plain dictionary representation.

Nodes live in flat glob stores keyed by string id: `node_type` holds each
node's type tag, `node_attrs` its scalar fields, `node_children` its child
adjacency as field-name -> list of child ids (with `list_fields` remembering
which fields were lists rather than single children), and `node_loc` its
optional source location. `es_node_to_dict` walks that adjacency and rebuilds
the nested dict shape, skipping the type/loc bookkeeping fields and None
values just like the object-based converter did.
"""

glob node_type: dict[str, str] = {};
glob node_attrs: dict[str, dict] = {};
glob node_children: dict[str, dict[str, list[str]]] = {};
glob list_fields: dict[str, list[str]] = {};
glob node_loc: dict[str, dict] = {};

def es_node_to_dict(nid: str) -> dict {
    result: dict = {"type": node_type[nid]};
    for (key, value) in node_attrs.get(nid, {}).items() {
        if key in ("type", "loc") or value is None {
            continue;
        }
        result[key] = value;
    }
    for (key, child_ids) in node_children.get(nid, {}).items() {
        if key in list_fields.get(nid, []) {
            result[key] = [es_node_to_dict(cid) for cid in child_ids];
        } else {
            result[key] = es_node_to_dict(child_ids[0]);
        }
    }
    loc = node_loc.get(nid, {});
    if len(loc) > 0 {
        start = loc.get("start");
        end = loc.get("end");
        result["loc"] = {
            "source": loc.get("source"),
            "start": {"line": start["line"], "column": start["column"]}
                if start is not None
                else None,
            "end": {"line": end["line"], "column": end["column"]}
                if end is not None
                else None
        };
    }
    return result;
}

