"""Jac library-mode surface rewritten as a plain dict-graph helper module.

The object-spatial runtime aliases (Node, Edge, Walker, spawn, visit,
connect, disconnect, refs, filter_on, assign_all, build_edge, destroy)
are replaced by ordinary functions over a dict-of-lists adjacency store.
API names stay stable so callers keep working against the same surface.
"""

glob node_store: dict[str, dict] = {};
glob adjacency: dict[str, list[str]] = {};
glob edge_meta: dict[str, dict] = {};

glob __all__ = [
    'create_node', 'connect', 'disconnect', 'build_edge', 'destroy',
    'refs', 'filter_on', 'assign_all', 'spawn_traversal', 'root_id'
];

glob root_id: str = "root";

def create_node(node_id: str, kind: str, fields: dict) -> str {
    node_store[node_id] = {"kind": kind, "fields": fields};
    if node_id not in adjacency {
        adjacency[node_id] = [];
    }
    return node_id;
}

def build_edge(src: str, tgt: str, kind: str, meta: dict) -> str {
    key = src + "->" + tgt;
    edge_meta[key] = {"kind": kind, "meta": meta};
    return key;
}

def connect(src: str, tgt: str, kind: str = "generic") -> None {
    if src not in adjacency {
        adjacency[src] = [];
    }
    adjacency[src].append(tgt);
    build_edge(src, tgt, kind, {});
}

def disconnect(src: str, tgt: str) -> None {
    if src in adjacency and tgt in adjacency[src] {
        adjacency[src].remove(tgt);
    }
    key = src + "->" + tgt;
    if key in edge_meta {
        edge_meta.pop(key);
    }
}

def destroy(node_id: str) -> None {
    if node_id in node_store {
        node_store.pop(node_id);
    }
    if node_id in adjacency {
        adjacency.pop(node_id);
    }
    for src in list(adjacency.keys()) {
        if node_id in adjacency[src] {
            adjacency[src].remove(node_id);
        }
    }
}

def refs(node_id: str) -> list[str] {
    return list(adjacency.get(node_id, []));
}

def filter_on(ids: list[str], kind: str) -> list[str] {
    out: list[str] = [];
    for i in ids {
        rec = node_store.get(i);
        if rec is not None and str(rec["kind"]) == kind {
