def index_sub_nodes(top: str) -> None {
    tab: dict[str, list[str]] = {};
    stack: list[str] = list(node_kids.get(top, []));
    while len(stack) > 0 {
        cur = stack.pop();
        kind = node_kind[cur];
        if kind not in tab {
            tab[kind] = [];
        }
        tab[kind].append(cur);
        for kid in node_kids.get(cur, []) {
            stack.append(kid);
        }
    }
