}

"""Get all sub node ids of a kind: use the node's table when indexed,
else brute-force over the kid map (or refuse, like the original)."""
def get_all_sub_nodes(nid: str, kind: str, brute_force: bool = False) -> list[str] {
    result: list[str] = [];
    if nid == "" {
        return result;
    }
    tab = sub_node_tab.get(nid, {});
    if len(tab) > 0 {
        for i in tab.get(kind, []) {
            result.append(i);
