"""TypeScript declaration generation rewritten over a plain dict module
record (exported functions / classes / globals as lists of dicts)."""

def jac_type_to_ts(t: str) -> str {
    mapping: dict[str, str] = {
        "str": "string", "int": "number", "float": "number",
        "bool": "boolean", "list": "unknown[]", "dict": "Record<string, unknown>",
        "None": "void", "any": "unknown"
    };
    return str(mapping.get(t, t));
}

"""Generate the .d.ts declaration text for a module record's exported
functions, classes, and globals. Returns "" when nothing is exported."""
def dts_for_module(mod: dict) -> str {
    lines: list[str] = [];
    for fn in list(mod.get("functions", [])) {
        params: list[str] = [];
        for p in list(fn["params"]) {
            params.append(str(p["name"]) + ": " + jac_type_to_ts(str(p["type"])));
        }
        lines.append(
            "export declare function " + str(fn["name"]) + "("
            + ", ".join(params) + "): " + jac_type_to_ts(str(fn["ret"])) + ";"
        );
    }
    for cls in list(mod.get("classes", [])) {
        lines.append("export declare class " + str(cls["name"]) + " {");
        for f in list(cls["fields"]) {
            lines.append("    " + str(f["name"]) + ": " + jac_type_to_ts(str(f["type"])) + ";");
        }
        lines.append("}");
    }
    for g in list(mod.get("globals", [])) {
        lines.append("export declare const " + str(g["name"]) + ": " + jac_type_to_ts(str(g["type"])) + ";");
    }
    if len(lines) == 0 {
        return "";
    }
    return "\n".join(lines) + "\n";
}

