def add_graph_edge(src: str, tgt: str, edge_type: str = "generic") -> None {
    graph_edges[src].append({"to": tgt, "type": edge_type});
}

"""Render the dict graph as DOT, walking from *start* with a queue (BFS) or
stack (DFS), honoring depth / node / edge limits and an edge-type filter."""
def printgraph(
    start: str,
    depth: int = -1,
    edge_type: list[str] = [],
    bfs: bool = True,
    edge_limit: int = 512,
    node_limit: int = 512
) -> str {
    lines: list[str] = ["digraph {"];
    visited: list[str] = [];
    frontier: list[tuple] = [(start, 0)];
    n_edges = 0;
    while len(frontier) > 0 {
        if bfs {
            (cur, d) = frontier.pop(0);
        } else {
            (cur, d) = frontier.pop();
        }
        if cur in visited {
            continue;
        }
        if len(visited) >= node_limit {
            break;
        }
        visited.append(cur);
        lines.append('  "' + cur + '" [label="' + str(graph_nodes[cur]["label"]) + '"];');
        if depth >= 0 and d >= depth {
            continue;
        }
        for e in graph_edges.get(cur, []) {
            if len(edge_type) > 0 and str(e["type"]) not in edge_type {
                continue;
            }
            if n_edges >= edge_limit {
                break;
            }
            n_edges = n_edges + 1;
            lines.append('  "' + cur + '" -> "' + str(e["to"]) + '";');
            frontier.append((str(e["to"]), d + 1));
        }
    }
    lines.append("}");
    return "\n".join(lines);
}

def jac_graph_json() -> str {
    return json.dumps({"nodes": graph_nodes, "edges": graph_edges});
}

def restspec(**specs: any) -> dict {
    return {"restspec": specs};
}

def schedule(**kwargs: any) -> dict {
    return {"schedule": kwargs};
}

