"""Scheduler rewritten as plain functions over a task list — no objects, no
background thread; a virtual clock loop drains due tasks deterministically."""

import heapq;

glob tasks: list[dict] = [];
glob run_log: list[str] = [];

def make_spec(date: str = "", interval: float = 0.0, cron: str = "") -> dict {
    return {"date": date, "interval": interval, "cron": cron};
}

def register(name: str, target: any, spec: dict) -> None {
    tasks.append({
        "name": name, "target": target, "spec": spec,
        "next_run": -1.0, "last_run": -1.0
    });
}

def compute_date(date_val: float, now: float) -> float {
    if date_val > now {
        return date_val;
    }
    return -1.0;
}

"""Next run time for a spec given the current (virtual) time; -1 = never."""
def compute_next_run(spec: dict, now: float) -> float {
    if str(spec["date"]) != "" {
        return compute_date(float(str(spec["date"])), now);
    }
    if float(str(spec["interval"])) > 0.0 {
        return now + float(str(spec["interval"]));
    }
    return -1.0;
}

def execute(task: dict, now: float) -> None {
    task["last_run"] = now;
    fn = task["target"];
    run_log.append(str(task["name"]) + "@" + str(now) + ":" + str(fn()));
}

def has_pending(now: float) -> bool {
    for t in tasks {
        if float(str(t["next_run"])) >= 0.0 {
            return True;
        }
    }
    return False;
}

"""Deterministic run loop over a min-heap of (when, index) pairs."""
def run_loop(until: float) -> None {
    heap: list = [];
    i = 0;
    while i < len(tasks) {
        nr = compute_next_run(tasks[i]["spec"], 0.0);
        tasks[i]["next_run"] = nr;
        if nr >= 0.0 {
            heapq.heappush(heap, (nr, i));
        }
        i = i + 1;
    }
    while len(heap) > 0 {
        (when, idx) = heapq.heappop(heap);
        if when > until {
            break;
        }
        task = tasks[idx];
        execute(task, when);
        spec = task["spec"];
        if float(str(spec["interval"])) > 0.0 {
            nxt = when + float(str(spec["interval"]));
            task["next_run"] = nxt;
            heapq.heappush(heap, (nxt, idx));
        } else {
            task["next_run"] = -1.0;
        }
    }
}

def tick_metrics() -> str {
    return "ok";
}

def one_shot() -> str {
    return "fired";
}

with entry {
    register("metrics", tick_metrics, make_spec(interval=2.0));
    register("report", one_shot, make_spec(date="5.0"));
    run_loop(6.0);
    for line in run_log {
        print(line);
    }
    print("pending after horizon: " + str(has_pending(6.0)));
}

