type_map dict of records rather than obj wrappers over live classes."""

# node kind -> {"kids": [ {"name","typ","default"} ]}
glob type_map: dict[str, dict] = {};

def make_kid_info(name: str, typ: str, default_val: str = "") -> dict {
    return {"name": name, "typ": typ, "default": default_val};
}

"""Register metadata about one AST node kind (UniNodeInfo.process)."""
def process(kind: str, kids: list[dict]) -> None {
    type_map[kind] = {"kids": kids};
}

def pascal_to_snake(name: str) -> str {
    out = "";
    i = 0;
    for ch in name {
        if ch.isupper() and i > 0 {
            out = out + "_";
        }
        out = out + ch.lower();
        i = i + 1;
    }
    return out;
}

"""Emit a pass template with enter/exit stubs for every registered kind."""
def pass_template() -> str {
    lines: list[str] = ["class Pass:"];
    for kind in sorted(list(type_map.keys())) {
        snake = pascal_to_snake(kind);
        lines.append("    def enter_" + snake + "(self, nd): ...");
        lines.append("    def exit_" + snake + "(self, nd): ...");
    }
    return "\n".join(lines);
}

"""Summarize registered node kinds and their kid fields."""
def py_uni_nodes() -> str {
    lines: list[str] = [];
    for kind in sorted(list(type_map.keys())) {
        parts: list[str] = [];
        for k in list(type_map[kind]["kids"]) {
            entry_txt = str(k["name"]) + ": " + str(k["typ"]);
            if str(k["default"]) != "" {
                entry_txt = entry_txt + " = " + str(k["default"]);
            }
            parts.append(entry_txt);
        }
        lines.append(kind + "(" + ", ".join(parts) + ")");
    }
    return "\n".join(lines);
}

"""Dispatch a small ir command (dot/print) over the registry."""
def ir(args: list[str]) -> str {
    if len(args) == 0 {
        return "usage: ir <dot|print>";
    }
    cmd = args[0];
    if cmd == "print" {
        return py_uni_nodes();
    }
    if cmd == "dot" {
        lines: list[str] = ["digraph {"];
        for kind in sorted(list(type_map.keys())) {
            for k in list(type_map[kind]["kids"]) {
                lines.append('  "' + kind + '" -> "' + str(k["typ"]) + '";');
            }
        }
        lines.append("}");
        return "\n".join(lines);
    }
    return "unknown command: " + cmd;
}

