    today = "2020-01-01";
    if today not in book {
        book[today] = [];
    }
    visitor = {
        "name": name.strip()[:40] or "anonymous",
        "message": message.strip()[:200],
        "created_at": "2020-01-01T00:00:00Z"
    };
    book[today].append(visitor);
    reports.append(to_view(visitor));
    return reports;
