"""RL driver (graph): social_graph.get_trending.tally.

Origin: this_is_jac/littlex/social_graph.jac. Fans out over a profile's tweets
held in a plain list of dicts, tallies hashtags (deduped by tweet id), and
returns the top tags. The entry block builds fixed tweet records and prints a
deterministic (tag, count) projection.
"""

def tally(counts: dict[str, int], seen: dict[str, bool], tweet: dict) -> None {
    tid = tweet["id"];
    if tid in seen {
        return;
    }
    seen[tid] = True;
    for word in tweet["content"].split() {
        if word.startswith("#") and len(word) > 1 {
            tag = word.lower().rstrip(".,!?;:");
            counts[tag] = counts.get(tag, 0) + 1;
        }
    }
}

def count_of(tc: any) -> int {
    return tc[1];
}

def get_trending(tweets: list[dict]) -> list {
    counts: dict[str, int] = {};
    seen: dict[str, bool] = {};
    queue: list[dict] = [];
    for t in tweets {
        queue.append(t);
    }
    while len(queue) > 0 {
        tw = queue.pop(0);
        tally(counts, seen, tw);
    }
    tags: list = [];
    for t in counts.keys() {
        tags.append((t, counts[t]));
    }
    tags.sort(key=count_of, reverse=True);
    return tags[:8];
}

