    tweets = [
        {"id": "t1", "content": "loving #jac and #jac again, also #rl"},
        {"id": "t2", "content": "#rl scaling with #jac"},
        {"id": "t3", "content": "no tags here"}
    ];
    out = get_trending(tweets);
    print(out);
}

